// Self-supporting horizontal passage for PBF-LB/M: a teardrop channel instead
// of a round bore, so no downward-facing roof is flatter than the overhang limit.
// Pipeline: closed STL -> solid voxels -> wall check -> teardrop cut -> STL.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

/// <summary>
/// Teardrop cross-section in the y-z plane, extruded along x. Below the two
/// tangent points it is the round bore; above them two flat flanks at
/// fFlankDeg from the horizontal meet at an apex r / cos(flank) above the axis.
/// Each piece is an exact signed distance inside the shape, so the zero level
/// set is exact. fGrowMM offsets the whole shape outward for wall checks.
/// </summary>
public sealed class TeardropChannelX : IImplicit
{
    readonly float m_fY, m_fZ;       // channel axis position (mm)
    readonly float m_fR;             // radius of the round lower part (mm)
    readonly float m_fSin, m_fCos;   // flank angle from the horizontal
    readonly float m_fGrow;          // outward offset (mm), 0 for the channel itself

    public TeardropChannelX(float fY, float fZ, float fRadiusMM, float fFlankDeg, float fGrowMM = 0f)
    {
        if (fRadiusMM <= 0 || fFlankDeg <= 0 || fFlankDeg >= 90 || fGrowMM < 0)
            throw new ArgumentException("Invalid channel parameters");
        m_fY = fY; m_fZ = fZ; m_fR = fRadiusMM; m_fGrow = fGrowMM;
        float fRad = fFlankDeg * MathF.PI / 180f;
        m_fSin = MathF.Sin(fRad);
        m_fCos = MathF.Cos(fRad);
    }

    /// <summary>Height of the apex above the axis, in mm.</summary>
    public float fApexMM => m_fR / m_fCos;

    /// <summary>Exact cross-section area in mm2: circle minus the upper sector plus the roof kite.</summary>
    public float fAreaMM2 => MathF.PI * m_fR * m_fR * (1f - MathF.Acos(m_fCos) / MathF.PI)
                             + m_fR * m_fR * m_fSin / m_fCos;

    // Thread-safe: only reads fields.
    public float fSignedDistance(in Vector3 vec)
    {
        float fU = MathF.Abs(vec.Y - m_fY);      // the section is symmetric about y = m_fY
        float fV = vec.Z - m_fZ;                 // height above the axis, +z is the build direction
        float fRound = MathF.Sqrt(fU * fU + fV * fV) - m_fR;

        // Roof wedge: under both flanks and above the tangent points, which
        // sit at height r cos(flank). The flank's unit normal is (sin, cos).
        float fFlank = fU * m_fSin + fV * m_fCos - m_fR;
        float fAbove = m_fR * m_fCos - fV;
        float fRoof = MathF.Max(fFlank, fAbove);

        // Union of bore and roof, then the optional outward offset.
        return fRound - m_fGrow;   // NEGATIVE CONTROL: plain round bore, roof ignored
    }
}

public static class SelfSupportingChannel
{
    // Design inputs. Lengths in millimetres, angles in degrees from the plate.
    const float fChannelY    = -15f;   // axis position across the part
    const float fChannelZ    =   8f;   // axis height above the build plate
    const float fRadiusMM    =   3f;   // round lower part, 6 mm wide
    const float fFlankDeg    =  50f;   // roof flanks, kept 5 deg steeper than the limit
    const float fOverhangDeg =  45f;   // process assumption, see the explanation
    const float fMinWallMM   =   1f;   // minimum printable wall (assumption)

    public static void Main(string[] args)
    {
        // Usage: SelfSupportingChannel <part.stl> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // Refuse a roof that would itself be an unsupported overhang, and a
        // voxel size that cannot resolve the thinnest wall.
        if (fFlankDeg <= fOverhangDeg)
            throw new ArgumentException($"Flank {fFlankDeg} deg is not steeper than the {fOverhangDeg} deg limit");
        if (lib.fVoxelSize > fMinWallMM / 3f)
            throw new ArgumentException($"Voxel size {lib.fVoxelSize} mm cannot resolve {fMinWallMM} mm walls");

        // 1. Load the closed, millimetre-scaled mesh and voxelise it.
        using Mesh mshIn = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(mshIn);
        if (voxBody.bIsEmpty()) throw new InvalidDataException("The mesh produced no volume; is it closed?");
        BBox3 oBox = voxBody.oCalculateBoundingBox();

        TeardropChannelX xChannel = new(fChannelY, fChannelZ, fRadiusMM, fFlankDeg);

        // A y-z window comfortably larger than the grown section. An
        // unbounded implicit is only rendered inside a box.
        float fHalfY = 2f * fRadiusMM + 2f * fMinWallMM;
        float fZLow  = fChannelZ - fRadiusMM - 2f * fMinWallMM;
        float fZHigh = fChannelZ + xChannel.fApexMM + 3f * fMinWallMM;

        // 2. Wall check before cutting. Grow the channel by the minimum wall
        //    and render it away from the two open ends. Any part of it left
        //    after subtracting the body lies outside the part, so somewhere
        //    the wall would be thinner than fMinWallMM.
        float fEndMM = fMinWallMM + 2f;   // keep clear of the end faces and their edge rounds
        BBox3 oInner = new(new Vector3(oBox.vecMin.X + fEndMM, fChannelY - fHalfY, fZLow),
                           new Vector3(oBox.vecMax.X - fEndMM, fChannelY + fHalfY, fZHigh));
        TeardropChannelX xGrown = new(fChannelY, fChannelZ, fRadiusMM, fFlankDeg, fMinWallMM);
        using Voxels voxProbe = new(lib, xGrown, oInner);
        using Voxels voxOutside = voxProbe.voxBoolSubtract(voxBody);
        if (!voxOutside.bIsEmpty())
            throw new InvalidDataException($"Less than {fMinWallMM} mm of wall around the channel; move or shrink it");

        // 3. Cut the channel over the full length plus a margin, so both
        //    ends are open. A passage open at both ends cannot trap powder.
        BBox3 oCut = new(new Vector3(oBox.vecMin.X - 2f, fChannelY - fHalfY, fZLow),
                         new Vector3(oBox.vecMax.X + 2f, fChannelY + fHalfY, fZHigh));
        using Voxels voxChannel = new(lib, xChannel, oCut);
        using Voxels voxPart = voxBody.voxBoolSubtract(voxChannel);

        // 4. Measure what was removed and compare with area x length. A large
        //    shortfall means the channel missed the part or left it early.
        voxBody.CalculateProperties(out float fBodyMM3, out _);
        voxPart.CalculateProperties(out float fPartMM3, out _);
        float fRemovedMM3 = fBodyMM3 - fPartMM3;
        float fExpectedMM3 = xChannel.fAreaMM2 * (oBox.vecMax.X - oBox.vecMin.X);
        if (fRemovedMM3 < 0.8f * fExpectedMM3)
            throw new InvalidDataException($"Channel removed {fRemovedMM3:F0} mm3, expected about {fExpectedMM3:F0} mm3");

        // 5. Export. Weld vertices onto the checker's 0.0001 mm cell grid and
        //    drop faces that collapse, so the STL has no degenerate triangles.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxPart.mshAsMesh();
        var triangles = new List<(Vector3 A, Vector3 B, Vector3 C)>();
        for (int i = 0; i < mshOut.nTriangleCount(); i++)
        {
            mshOut.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
            triangles.Add((a, b, c));
        }
        var clean = MeshCleanup.WeldAndFilter(triangles, 0.0001f, out int nRemoved, out float fMoved);
        if (clean.Count == 0) throw new InvalidDataException("Export cleanup produced an empty mesh");
        using Mesh mshClean = new(lib);
        foreach (var t in clean) mshClean.nAddTriangle(t.A, t.B, t.C);
        mshClean.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);

        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Apex {0:F2} mm above the axis, removed {1:F0} mm3 (expected {2:F0}), relative volume {3:F3}",
            xChannel.fApexMM, fRemovedMM3, fExpectedMM3, fPartMM3 / fBodyMM3));
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Export cleanup removed {0} faces; maximum vertex displacement {1:G9} mm", nRemoved, fMoved));
    }
}

// Numerical export cleanup, independent of PicoGK and physical qualification.
// The corpus embeds this exact source so its C# example stays self-contained.
public static class MeshCleanup
{
    // Weld onto the first vertex in each quantized cell, preserving winding.
    // Vertices are actually replaced; merely dropping tiny faces could leave holes.
    public static List<(Vector3 A, Vector3 B, Vector3 C)> WeldAndFilter(
        IEnumerable<(Vector3 A, Vector3 B, Vector3 C)> input, float tolerance,
        out int removed, out float maxDisplacement)
    {
        if (!float.IsFinite(tolerance) || tolerance <= 0 || !float.IsFinite(1f / tolerance) ||
            !float.IsFinite(MathF.Sqrt(3) * tolerance))
            throw new ArgumentOutOfRangeException(nameof(tolerance));
        float scale = 1f / tolerance;
        var vertices = new Dictionary<(long, long, long), Vector3>();
        var result = new List<(Vector3, Vector3, Vector3)>();
        int dropped = 0;
        float moved = 0;

        Vector3 Weld(Vector3 v)
        {
            if (!float.IsFinite(v.X) || !float.IsFinite(v.Y) || !float.IsFinite(v.Z))
                throw new ArgumentException("Nonfinite mesh vertex");
            // Same rounded-cell convention as the independent STL checker.
            var key = (checked((long)MathF.Round(v.X * scale)),
                       checked((long)MathF.Round(v.Y * scale)),
                       checked((long)MathF.Round(v.Z * scale)));
            if (!vertices.TryGetValue(key, out Vector3 canonical))
                vertices[key] = canonical = v;
            float displacement = Vector3.Distance(v, canonical);
            // Large coordinates can lose precision during float quantization.
            // Refuse a weld that exceeds the cell-diagonal movement budget.
            if (!float.IsFinite(displacement) || displacement > MathF.Sqrt(3) * tolerance)
                throw new ArgumentException("Vertex weld exceeds the declared tolerance budget");
            moved = MathF.Max(moved, displacement);
            return canonical;
        }

        foreach (var t in input)
        {
            Vector3 a = Weld(t.A), b = Weld(t.B), c = Weld(t.C);
            Vector3 cross = Vector3.Cross(b - a, c - a);
            if (!float.IsFinite(cross.X) || !float.IsFinite(cross.Y) || !float.IsFinite(cross.Z))
                throw new ArgumentException("Nonfinite triangle area");
            // Remove collapsed and numerically zero-area faces after welding.
            if (a == b || b == c || a == c || cross.LengthSquared() == 0)
            {
                dropped++;
                continue;
            }
            result.Add((a, b, c));
        }
        removed = dropped;
        maxDisplacement = moved;
        return result;
    }
}
